/**
 * Merge profile data with extended attributes, filling defaults for missing entries.
 */
export function getCharAttrs(profile) {
  const explicit = CHARACTER_ATTRIBUTES[profile.id]
  if (explicit) return explicit
  // Derive sensible defaults from existing profile data
  const isVillain = profile.affiliation === 'villain'
  const teamMap = { avengers: 'avengers', guardians: 'guardians', xmen: 'xmen', defenders: 'defenders', shield: 'shield' }
  return {
    gender:     'male',
    origin:     'earth',
    powerLevel: profile.affiliation === 'other' ? 'street' : 'enhanced',
    status:     isVillain ? 'villain' : 'hero',
    deceased:   false,
    teams:      teamMap[profile.affiliation] ? [teamMap[profile.affiliation]] : [],
    powerTypes: [],
  }
}
